function renderOverviewHtml(deck) {
  const width = Math.max(1, Math.round(deck.canvas.width));
  const height = Math.max(1, Math.round(deck.canvas.height));
  const frames = deck.slides.map((slide) => {
    return `    <article class="overview-slide">
      <header>
        <span>${slide.index}</span>
        <a href="./slides/${slide.id}.html" target="_blank" rel="noreferrer">${escapeHtml(slide.id)}</a>
      </header>
      <div class="overview-frame-shell">
        <div class="overview-frame" style="width: ${width}px; height: ${height}px;">
          <iframe title="${escapeHtml(`${slide.index}. ${slide.id}`)}" src="./slides/${slide.id}.html" width="${width}" height="${height}" loading="lazy"></iframe>
        </div>
      </div>
    </article>`;
  }).join("\n");
  return `<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(deck.source.fileName)} - overview</title>
  <style>
    :root {
      --overview-scale: 0.42;
      --overview-gap: 24px;
      font-family: Aptos, Arial, sans-serif;
      color: #111827;
      background: #f3f4f6;
    }

    body {
      margin: 0;
    }

    .overview {
      padding: 24px;
    }

    .overview > header {
      display: flex;
      align-items: baseline;
      gap: 16px;
      margin-bottom: 20px;
    }

    h1 {
      margin: 0;
      font-size: 20px;
      font-weight: 700;
    }

    .overview-count {
      color: #4b5563;
      font-size: 13px;
    }

    .overview-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(calc(${width}px * var(--overview-scale)), 1fr));
      gap: var(--overview-gap);
      align-items: start;
    }

    .overview-slide {
      width: calc(${width}px * var(--overview-scale));
    }

    .overview-slide header {
      display: flex;
      justify-content: space-between;
      gap: 12px;
      margin-bottom: 8px;
      font-size: 13px;
      line-height: 1.4;
    }

    .overview-slide a {
      color: #2563eb;
      text-decoration: none;
    }

    .overview-slide a:hover {
      text-decoration: underline;
    }

    .overview-frame-shell {
      position: relative;
      width: calc(${width}px * var(--overview-scale));
      height: calc(${height}px * var(--overview-scale));
    }

    .overview-frame {
      position: absolute;
      left: 0;
      top: 0;
      transform: scale(var(--overview-scale));
      transform-origin: top left;
      border: 1px solid #d1d5db;
      background: #ffffff;
      box-shadow: 0 8px 24px rgba(15, 23, 42, 0.14);
    }

    .overview-frame iframe {
      display: block;
      border: 0;
    }
  </style>
</head>
<body>
  <main class="overview">
    <header>
      <h1>${escapeHtml(deck.source.fileName)}</h1>
      <span class="overview-count">${deck.slides.length} slides</span>
    </header>
    <section class="overview-grid">
${frames}
    </section>
  </main>
</body>
</html>
`;
}

